const expenses = $input.first().json;
const businessId = $('Webhook: Check Anomalies').item.json.body?.businessId || $('Webhook: Check Anomalies').item.json.businessId;

const alerts = [];

if (Array.isArray(expenses)) {
  for (const exp of expenses) {
    // 1. Gasto inusualmente alto (> 5000€)
    if (Number(exp.total_amount) >= 5000) {
      alerts.push({
        business_id: businessId,
        severity: 'medium',
        type: 'UNUSUAL_EXPENSE',
        title: 'Importe de gasto elevado (> 5.000€)',
        description: `El gasto de ${exp.total_amount}€ (${exp.description || 'sin descripción'}) requiere comprobante formal.`,
        evidence: { expenseId: exp.id, totalAmount: exp.total_amount },
        entity_type: 'expense',
        entity_id: exp.id,
        source: 'n8n',
        status: 'OPEN'
      });
    }

    // 2. Falta de desglose de IVA
    if (Number(exp.total_amount) > 0 && (exp.vat_rate === null || exp.vat_rate === undefined)) {
      alerts.push({
        business_id: businessId,
        severity: 'medium',
        type: 'MISSING_VAT_DATA',
        title: 'Gasto sin tipo de IVA desglosado',
        description: `El gasto de ${exp.total_amount}€ no especifica tipo de IVA aplicable.`,
        evidence: { expenseId: exp.id },
        entity_type: 'expense',
        entity_id: exp.id,
        source: 'n8n',
        status: 'OPEN'
      });
    }

    // 3. Gasto pendiente de revisión
    if (exp.validation_status === 'PENDING') {
      alerts.push({
        business_id: businessId,
        severity: 'low',
        type: 'UNREVIEWED_EXPENSE',
        title: 'Gasto pendiente de validación',
        description: `El gasto registrado el ${exp.date} (${exp.total_amount}€) no ha sido validado.`,
        evidence: { expenseId: exp.id },
        entity_type: 'expense',
        entity_id: exp.id,
        source: 'n8n',
        status: 'OPEN'
      });
    }
  }
}

return {
  json: {
    businessId,
    alertsCount: alerts.length,
    alerts
  }
};
